  fc.record(BASE), // control: must stay identical
  withField("id"),
  withField("email"),
  withField("name"),
  withField("age"),
  withField("website"),
  withField("ip"),
  withField("plan"),
  withField("flags"),
  withField("prefs"),
  withField("prefs"),
  chaosSignup,
);

