  basePort,
  fc.constantFrom("0", "65536", "-1", "8080 ", "", " ", "08080", "0x1f90", "1e4", "abc", "Infinity", "NaN", "9007199254740993"),
  fc.constant(undefined),
  fc.oneof(fc.integer(), fc.constant(null), fc.constant(true)),
);

const hostsPool = fc.oneof(
  fc.array(zonedIp, { minLength: 1, maxLength: 3 }),
  fc.tuple(fc.ipV4(), zonedIp), // one good + one zoned
  fc.array(fc.oneof(fc.ipV4(), ipv6Base, zonedIp, junkIp), { minLength: 1, maxLength: 4 }),
