  fc.constantFrom(Infinity, -Infinity, NaN),
  fc.constantFrom(Infinity, -Infinity),
  fc.constantFrom(0, -0, -1, 1, 5000, 1.5, 5e-324, -4e-323, 1e308, Number.MAX_VALUE, 2 ** 53, 1e21),
  fc.constant(undefined),
  fc.oneof(fc.double(), fc.integer(), fc.constantFrom("5000", "Infinity"), fc.constant(null), fc.constant(true)),
);

