  fc.tuple(fc.record({ ...CONFIG_BASE, [field]: CONFIG_POOLS[field] }), fc.boolean()).map(([rec, omit]) => (omit ? stripUndefined(rec) : rec));

const chaosConfig = fc.tuple(fc.record(CONFIG_POOLS), fc.boolean()).map(([rec, omit]) => (omit ? stripUndefined(rec) : rec));

const config = fc.oneof(
  fc.record(CONFIG_BASE), // control
  withConfigField("port"),
  withConfigField("hosts"),
  withConfigField("hosts"),
  withConfigField("timeoutMs"),
  withConfigField("timeoutMs"),
  chaosConfig,
);

