// Input generators for the differential fuzzer (fuzz/run.js). fast-check arbitraries.
// Exports { signup, config }.
//
// DESIGN: ONE FIELD AT A TIME.
// fuzz/run.js only counts an input as exercising a zod 4 behaviour change when
// *every other field is valid* (zod 3 accepted it, or the only field zod 3
// complained about is the field under test). A first draft that threw garbage at
// every field at once scored 2/7 coverage: almost every input had three other
// things wrong with it, so it proved nothing about the change under test and its
// diffs all collapsed into one unreadable "rejected by both" bucket.
//
// So: each branch below starts from a BASELINE that zod 3 and zod 4 both
// certainly accept -- dotted-quad IPv4 (no IPv6 regex quirks), ascii name,
// lowercase v1-v4 / variant-8-b uuid, fully specified `prefs` (so no default
// machinery is involved), plain `user@host.com` email -- and replaces exactly
// ONE field with an edge pool aimed at a known zod 4 change. Every diff then
// names its own cause.
//
// Pools are written to straddle each change's boundary (just inside / just
// outside), and each branch also mixes in "explicit undefined" vs "key omitted"
// for the optional fields, because zod 4 treats those two differently in places.
// One small `chaos` branch still perturbs everything at once, to check that
// multi-field error reports still compose the way they used to.

const fc = require("fast-check");

/* ------------------------------------------------------------------ helpers */

const hex = (n) => fc.stringMatching(new RegExp(`^[0-9a-f]{${n}}$`));
const pick = (chars) => fc.constantFrom(...chars.split(""));

// A uuid-SHAPED string with chosen version / variant nibbles.
const uuidOf = (versions, variants) =>
  fc
    .tuple(hex(8), hex(4), pick(versions), hex(3), pick(variants), hex(3), hex(12))
    .map(([a, b, ver, c, vari, d, e]) => `${a}-${b}-${ver}${c}-${vari}${d}-${e}`);

// Drop keys whose value is undefined -> "key missing" instead of "key present,
// value undefined". Both shapes are generated (see `withField`).
const stripUndefined = (o) => {
  const out = {};
  for (const k of Object.keys(o)) if (o[k] !== undefined) out[k] = o[k];
  return out;
};

/* ------------------------------------------------- baseline: valid for both */

const baseId = uuidOf("1234", "89ab"); // RFC version+variant: safe under either uuid regex
const baseEmail = fc
  .tuple(fc.stringMatching(/^[a-z][a-z0-9]{0,7}$/), fc.stringMatching(/^[a-z][a-z0-9]{0,7}$/), fc.constantFrom("com", "org", "io"))
  .map(([local, host, tld]) => `${local}@${host}.${tld}`);
const baseName = fc.stringMatching(/^[A-Za-z][A-Za-z ]{0,19}$/);
const baseAge = fc.integer({ min: 13, max: 120 });
const baseUrl = fc
  .tuple(fc.constantFrom("http", "https"), fc.stringMatching(/^[a-z][a-z0-9]{1,7}$/), fc.constantFrom("com", "org", "io"))
  .map(([scheme, host, tld]) => `${scheme}://${host}.${tld}/`);
const baseIp = fc.ipV4(); // deliberately NOT IPv6: keeps every ip diff attributable
const basePlan = fc.constantFrom("free", "pro", "team");
const baseFlags = fc.dictionary(fc.stringMatching(/^[a-z][a-z0-9_]{0,6}$/), fc.boolean(), { maxKeys: 3 });
const basePrefs = fc.record({ theme: fc.constantFrom("light", "dark"), retries: fc.integer({ min: 0, max: 9 }).map(String) });

const BASE = {
  id: baseId,
  email: baseEmail,
  name: baseName,
  age: baseAge,
  website: baseUrl,
  ip: baseIp,
  plan: basePlan,
  flags: baseFlags,
  prefs: basePrefs,
};

/* ------------------------------------------------------------- signup pools */

// CHANGE: zod 4 `z.uuid()` checks the version/variant bits; `z.guid()` (what
// src uses now) and zod 3's `.uuid()` are shape-only. Straddle the RFC bits.
const nonRfcUuid = fc.oneof(
  uuidOf("09abcdef", "89ab"), // version nibble outside 1-8
  uuidOf("1234", "01234567cdef"), // variant nibble outside 8-b
  uuidOf("09abcdef", "01234567cdef"), // both wrong
  fc.constant("00000000-0000-0000-0000-000000000000"), // nil uuid
  fc.constant("ffffffff-ffff-ffff-ffff-ffffffffffff"), // max uuid
);
const idPool = fc.oneof(
  nonRfcUuid,
  nonRfcUuid,
  uuidOf("1234", "89ab").map((s) => s.toUpperCase()), // case: should still be accepted
  fc.constantFrom(
    "",
    "not-a-uuid",
    "3f2504e04f8911d39a0c0305e82c3301", // no dashes
    "{3f2504e0-4f89-11d3-9a0c-0305e82c3301}", // braced
    "3f2504e0-4f89-11d3-9a0c-0305e82c33010", // one too long
    "3f2504e0-4f89-11d3-9a0c-0305e82c330g", // non-hex
    " 3f2504e0-4f89-11d3-9a0c-0305e82c3301", // leading space
    "3f2504e0-4f89-11d3-9a0c-0305e82c3301\n", // trailing newline
  ),
  fc.oneof(fc.integer(), fc.constant(null)),
);

const emailPool = fc.oneof(
  baseEmail,
  fc.constantFrom(
    "a@b.c",
    "a@b",
    "a@localhost",
    "A@B.COM",
    "a+tag@b.com",
    "a_b@c.io",
    "a@b-c.com",
    "a@b.co.uk",
    "a..b@c.com",
    ".a@c.com",
    "a.@c.com",
    "a@-b.com",
    "a@b..com",
    "a@[127.00.1]",
    '"a b"@c.com',
    "a@b.com ",
    " a@b.com",
    "a@b.com\n",
    "a@@b.com",
    "no-at-sign",
    "",
    "user@exa_mple.com",
    "user@xn--80ak6aa92e.com",
    "üser@exämple.com", // unicode local + domain
    `${"a".repeat(70)}@b.com`,
  ),
  fc.emailAddress(),
);

// CHANGE: zod 4 `.max()/.min()` count Unicode CODE POINTS; zod 3 counted UTF-16
// code units. src keeps zod 3's measure with a refine, so straddle it:
// 41-70 astral chars = >80 code units but <=80 code points.
const astralName = fc.array(fc.constantFrom("\u{1F600}", "\u{1F389}", "\u{1F680}", "\u{1D306}", "\u{1F44D}"), { minLength: 41, maxLength: 70 }).map((a) => a.join(""));
const namePool = fc.oneof(
  astralName,
  astralName,
  fc.array(fc.constant("\u{1F600}"), { minLength: 1, maxLength: 40 }).map((a) => a.join("")), // <=80 units, fine for both
  fc.stringMatching(/^[a-z]{80}$/),
  fc.stringMatching(/^[a-z]{81}$/),
  fc.constantFrom(
    "",
    " ",
    "é".repeat(45), // 90 combining code points AND 90 units
    "é".repeat(40), // 80 of each
    "\u{1F468}‍\u{1F469}‍\u{1F467}".repeat(12), // ZWJ families: graphemes << code points
    "a�b",
    "ß".repeat(81),
    "\t\n",
  ),
  fc.string({ unit: "grapheme", maxLength: 90 }),
  fc.oneof(fc.constant(null), fc.integer()),
);

// CHANGE: zod 4 `.int()` means SAFE integer (and z.number() rejects non-finite).
const agePool = fc.oneof(
  fc.constantFrom(2 ** 53, 2 ** 53 + 2, 1e16, 1e21, 2 ** 60, Number.MAX_VALUE), // integers, NOT safe integers
  fc.constantFrom(2 ** 53, Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER - 1, 13, 120, 12, 0, -1), // safe-integer boundary
  fc.constantFrom(13.5, 12.9, -0, NaN, Infinity, -Infinity),
  fc.constant(undefined),
  fc.oneof(fc.double(), fc.integer({ min: 13, max: 120 }).map(String), fc.constant(true)),
);

const websitePool = fc.oneof(
  baseUrl,
  fc.constantFrom(
    "http://localhost",
    "http://localhost:3000/a?b=c#d",
    "https://1.2.3.4/",
    "https://example.com:99999",
    "ftp://files.example.com/x",
    "mailto:a@b.com",
    "javascript:alert(1)",
    "data:text/plain,hi",
    "//example.com",
    "example.com",
    "https://",
    "http://",
    "https://exa mple.com",
    "https://ünïcode.com",
    "https://xn--80ak6aa92e.com",
    "http://a_b.com",
    "https://example..com",
    "https://example.com/ ",
    "HTTP://EXAMPLE.COM",
    "https://example.com\n",
    "",
  ),
  fc.webUrl(),
  fc.constant(undefined),
);

// CHANGE: zod 3 `.ip()` vs zod 4 `z.ipv4()/z.ipv6()` + src's zonedIpv6 refine.
const ipv6Base = fc.constantFrom("::1", "fe80::1", "2001:db8::1", "1:2:3:4:5:6:7:8", "abcd::1", "::");
