const junkIp = fc.constantFrom(
  "",
  "localhost",
  "1.2.3",
  "1.2.3.4.5",
  "256.1.1.1",
  "::g",
  "%eth0",
  "1.2.3.4%eth0", // zone on an IPv4: src's refine only allows IPv6 bases
  "fe80:::1%eth0",
);
