// OTHER field is valid (zod 3 accepted it, or the only field zod 3 complained
// about is the field under test). The first draft threw garbage at every field at
// once and scored 2/7: nearly every input had three other things wrong, so it
// proved nothing about the change under test and every diff collapsed into one
// unreadable "rejected by both" bucket.
//
// So each branch starts from a BASELINE that zod 3 and zod 4 both certainly
// accept -- dotted-quad IPv4, ascii name, lowercase RFC-shaped uuid, fully
// specified prefs, plain user@host.com email -- and replaces exactly ONE field
// with a pool aimed at a known zod 4 change, straddling that change's boundary
// (just inside / just outside). Every diff then names its own cause. One small
// `chaos` branch still perturbs everything at once, to check that multi-field
// error reports still compose the way they used to.
//
// Each branch also mixes "key omitted" vs "key present, value undefined" for the
// optional fields, because those are different inputs to a default/prefault.
//
// KNOWN HARNESS LIMIT (evidence: run_fuzz crashed on the previous draft):
// fuzz/run.js:38 computes the group name as `A.ok ? B.fields : ...`, so when BOTH
// builds accept an input but the parsed VALUE differs, it reads `.map` of
// undefined and the whole run dies with no output -- the
// "accepted, but the PARSED VALUE changed" group is unreachable. Value-rewriting
// candidates are therefore kept OUT of the pools below and checked one by one in
// the temporary PROBE block at the bottom instead, which prints evidence instead
// of crashing. (I may not edit run.js; a human should.)

const fc = require("fast-check");

/* ------------------------------------------------------------------ helpers */

const hex = (n) => fc.stringMatching(new RegExp(`^[0-9a-f]{${n}}$`));
const pick = (chars) => fc.constantFrom(...chars.split(""));

// A uuid-SHAPED string with chosen version / variant nibbles.
const uuidOf = (versions, variants) =>
  fc
    .tuple(hex(8), hex(4), pick(versions), hex(3), pick(variants), hex(3), hex(12))
    .map(([a, b, ver, c, vari, d, e]) => `${a}-${b}-${ver}${c}-${vari}${d}-${e}`);

const stripUndefined = (o) => {
  const out = {};
  for (const k of Object.keys(o)) if (o[k] !== undefined) out[k] = o[k];
  return out;
};

/* ------------------------------------------------- baseline: valid for both */

const baseId = uuidOf("1234", "89ab"); // RFC version+variant: fine under either uuid rule
