  id: baseId,
  email: baseEmail,
  name: baseName,
  age: baseAge,
  website: baseUrl,
  ip: baseIp,
  plan: basePlan,
  flags: baseFlags,
  prefs: basePrefs,
};

// Replace exactly one (or, for chaos, every) field; then either keep explicit
// `undefined` keys or drop them, so both shapes are generated.
const only = (patch) =>
  fc
    .tuple(fc.record({ ...BASE, ...patch }), fc.boolean())
    .map(([o, keepUndefined]) => (keepUndefined ? o : stripUndefined(o)));

/* ------------------------------------------------------------- signup pools */

// CHANGE 1: zod 4 `z.uuid()` enforces the version/variant nibbles; zod 3's
// `.uuid()` and zod 4's `z.guid()` (what src uses now) are shape-only.
const nonRfcUuid = fc.oneof(
