  nonRfcUuid,
  nonRfcUuid,
  nonRfcUuid,
  uuidOf("1234", "89ab"),
  fc.constantFrom(
    "00000000-0000-0000-0000-000000000000", // nil uuid
    "ffffffff-ffff-ffff-ffff-ffffffffffff", // max uuid
    "",
    "not-a-uuid",
    "3f2504e04f8911d39a0c0305e82c3301", // no dashes
    "{3f2504e0-4f89-11d3-9a0c-0305e82c3301}", // braced
    "3f2504e0-4f89-11d3-9a0c-0305e82c33010", // one too long
    "3f2504e0-4f89-11d3-9a0c-0305e82c330g", // non-hex
    " 3f2504e0-4f89-41d3-9a0c-0305e82c3301", // leading space
    "3f2504e0-4f89-41d3-9a0c-0305e82c3301\n", // trailing newline
    "3F2504E0-4F89-41D3-9A0C-0305E82C3301", // uppercase
  ),
  fc.constant(undefined),
  fc.constantFrom(null, 42),
);

const emailPool = fc.oneof(
  baseEmail,
  fc.constantFrom(
    "a@b.c",
    "a@b",
    "a@localhost",
    "A@B.COM",
    "a+tag@b.com",
    "a_b@c.io",
    "a@b-c.com",
    "a@b.co.uk",
    "a..b@c.com",
    ".a@c.com",
