  astralName,
  astralName,
  astralName,
  fc.array(fc.constantFrom(...ASTRAL), { minLength: 1, maxLength: 40 }).map((a) => a.join("")), // <=80 units: fine for both
  fc.stringMatching(/^[a-z]{80}$/),
  fc.stringMatching(/^[a-z]{81}$/),
  fc.constantFrom(
    "",
    " ",
    "é".repeat(80), // 80 code points AND 80 units
    "é".repeat(81), // 81 of each: over for both
    "ß".repeat(81),
    "é".repeat(45), // combining marks: 90 code points, 90 units
    "\u{1F468}‍\u{1F469}‍\u{1F467}".repeat(12), // ZWJ families: 96 units, 60 code points
    "a\tb",
  ),
  fc.constant(undefined),
  fc.constantFrom(null, 5),
);

// CHANGE 3: zod 4 `.int()` means SAFE integer (and z.number() rejects non-finite).
const agePool = fc.oneof(
  fc.constantFrom(2 ** 53, 2 ** 53 + 2, 1e16, 1e21, 2 ** 60, Number.MAX_VALUE, -(2 ** 53)), // integers, not SAFE integers
  fc.constantFrom(2 ** 53, 1e21, 9007199254740993),
  fc.constantFrom(Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER - 1, 13, 12, 14, 0, -1, 120), // safe-integer side
  fc.constantFrom(13.5, 12.9, -0, NaN, Infinity, -Infinity),
  fc.constant(undefined),
  fc.constant(undefined),
