// (missing trailing slash, uppercase scheme, stray spaces) are held back for the
// PROBE block -- see the harness-limit note at the top.
const websitePool = fc.oneof(
  baseUrl,
  fc.constantFrom(
    "http://localhost/",
    "https://1.2.3.4/",
    "https://a.com/p?q=1#f",
    "ftp://files.example.com/x",
    "mailto:a@b.com",
