// Input generators for the differential fuzzer (fuzz/run.js). fast-check arbitraries.
// Exports { signup, config }.
//
// This module must be PURE: requiring it only builds arbitraries. (An earlier
// draft printed probe lines at import time and buried run_fuzz's own report.)
//
// DESIGN: ONE FIELD AT A TIME, OFF A BASELINE BOTH VERSIONS ACCEPT.
// fuzz/run.js only counts an input as exercising a zod 4 behaviour change when
// *every other field is valid* (zod 3 accepted the input, or the only field zod 3
// complained about is the field under test). The first draft threw garbage at
// every field at once and scored 2/7: nearly every input had three other things
// wrong with it, so it proved nothing about the change under test and all its
// diffs collapsed into one unreadable "rejected by both" bucket.
//
// So every branch below starts from BASE -- dotted-quad IPv4 (no IPv6 regex
// quirks), ascii name, lowercase RFC-shaped uuid, plain user@host.com email,
// fully specified prefs (so no default machinery is involved) -- and replaces
// exactly ONE field with a pool aimed at a known zod 4 change, written to
// straddle that change's boundary (just inside / just outside). Every diff then
// names its own cause.
//
// Optional fields are generated both as "key omitted" and "key present, value
// undefined" (see withField's strip flag), because those are not always the same
// thing. One small `multi` branch replaces 2-3 fields at once, to check that
// multi-field error reports still compose the way they used to.

const fc = require("fast-check");

/* ------------------------------------------------------------------ helpers */

const hex = (n) => fc.stringMatching(new RegExp(`^[0-9a-f]{${n}}$`));
const pick = (chars) => fc.constantFrom(...chars.split(""));

// A uuid-SHAPED string with chosen version / variant nibbles.
const uuidOf = (versions, variants) =>
  fc
    .tuple(hex(8), hex(4), pick(versions), hex(3), pick(variants), hex(3), hex(12))
    .map(([a, b, ver, c, vari, d, e]) => `${a}-${b}-${ver}${c}-${vari}${d}-${e}`);

const stripUndefined = (o) => {
  const out = {};
  for (const k of Object.keys(o)) if (o[k] !== undefined) out[k] = o[k];
  return out;
};

const rep = (times, s) => new Array(times).fill(s).join("");

/* ------------------------------------------------- baseline: valid for both */

const baseId = uuidOf("1234", "89ab"); // RFC version+variant: safe under either uuid check
const baseEmail = fc
  .tuple(fc.stringMatching(/^[a-z][a-z0-9]{0,7}$/), fc.stringMatching(/^[a-z][a-z0-9]{0,7}$/), fc.constantFrom("com", "org", "io"))
  .map(([local, host, tld]) => `${local}@${host}.${tld}`);
const baseName = fc.stringMatching(/^[A-Za-z][A-Za-z ]{0,19}$/);
const baseAge = fc.integer({ min: 13, max: 120 });
const baseUrl = fc
  .tuple(fc.constantFrom("http", "https"), fc.stringMatching(/^[a-z][a-z0-9]{1,7}$/), fc.constantFrom("com", "org", "io"))
  .map(([scheme, host, tld]) => `${scheme}://${host}.${tld}/`);
const baseIp = fc.ipV4(); // deliberately NOT IPv6: keeps every ip diff attributable
const basePlan = fc.constantFrom("free", "pro", "team");
const baseFlags = fc.dictionary(fc.stringMatching(/^[a-z][a-z0-9_]{0,6}$/), fc.boolean(), { maxKeys: 3 });
const basePrefs = fc.record({ theme: fc.constantFrom("light", "dark"), retries: fc.integer({ min: 0, max: 9 }).map(String) });

const BASE = fc.record({
  id: baseId,
  email: baseEmail,
  name: baseName,
  age: baseAge,
  website: baseUrl,
  ip: baseIp,
  plan: basePlan,
  flags: baseFlags,
  prefs: basePrefs,
});

