  "::",
  "fe80::1",
  "2001:db8::1",
  "1:2:3:4:5:6:7:8",
  "abcd::1",
  "0000:0000:0000:0000:0000:0000:0000:0001",
  "::ffff:1.2.3.4", // IPv4-mapped
  "::1.2.3.4",
  "1:2:3:4:5:6:1.2.3.4", // embedded IPv4 in a full address
