const ipv4Pool = fc.constantFrom(
  "0.0.0.0",
  "255.255.255.255",
  "10.0.0.1",
  "1.2.3.04", // leading zero
  "01.2.3.4",
  "1.2.3",
  "1.2.3.4.5",
  "256.1.1.1",
  "1.2.3.4 ",
  "1.2.3.-4",
  "0x7f.0.0.1",
  "127.1",
