const ipPool = fc.oneof(
  { arbitrary: zonedIp, weight: 6 }, // the documented change
  { arbitrary: ipv6Plain, weight: 4 },
  { arbitrary: ipv4Pool, weight: 2 },
  { arbitrary: junkIp, weight: 2 },
  { arbitrary: fc.ipV6(), weight: 2 },
  { arbitrary: fc.ipV6().map((a) => `${a}%eth0`), weight: 2 },
  { arbitrary: fc.ipV4Extended(), weight: 1 },
  { arbitrary: fc.oneof(fc.constant(null), fc.integer(), fc.constant(undefined)), weight: 1 },
);

// z.nativeEnum(Plan) -> z.enum(Plan)
const planPool = fc.oneof(
  { arbitrary: basePlan, weight: 2 },
  { arbitrary: fc.constantFrom("Free", "FREE", "enterprise", "", " free", "free ", "0"), weight: 4 },
  { arbitrary: fc.oneof(fc.constant(null), fc.constant(undefined), fc.integer(), fc.constant(true)), weight: 2 },
