  { arbitrary: fc.record({ retries: retriesPool }), weight: 2 }, // theme defaulted
  { arbitrary: fc.record({ theme: fc.constantFrom("light", "dark"), retries: retriesPool }), weight: 2 },
  { arbitrary: fc.record({ theme: fc.constantFrom("Light", "", "system"), retries: retriesPool }), weight: 1 },
