  { arbitrary: fc.record({ theme: fc.constantFrom("light", "dark"), retries: fc.oneof(fc.integer(), fc.constant(null)) }), weight: 1 },
  { arbitrary: fc.record({ theme: fc.constantFrom("light", "dark"), retries: retriesPool, extra: fc.constant(1) }), weight: 1 },
  { arbitrary: fc.oneof(fc.constant(null), fc.constant("x"), fc.constant([]), fc.integer()), weight: 1 },
