/* ---------------------------------------------------- assembling the signup */

// Replace exactly one field. `strip` decides between "key omitted" and
// "key present with value undefined" when the pool produced undefined.
const withField = (base, field, pool) =>
  fc.tuple(base, pool, fc.boolean()).map(([b, v, strip]) => {
    const o = { ...b, [field]: v };
    return strip ? stripUndefined(o) : o;
  });

const SIGNUP_POOLS = {
  id: idPool,
  email: emailPool,
  name: namePool,
  age: agePool,
  website: websitePool,
  ip: ipPool,
  plan: planPool,
  flags: flagsPool,
  prefs: prefsPool,
};

// A few fields wrong at once: checks that multi-field error reports still
// compose. Kept narrow (2-3 fields, same pools) so each diff stays attributable.
const multi = (base, pools) => {
  const keys = Object.keys(pools);
  return fc.uniqueArray(fc.constantFrom(...keys), { minLength: 2, maxLength: 3 }).chain((fields) =>
    fc.tuple(base, ...fields.map((f) => pools[f])).map(([b, ...vals]) => {
      const o = { ...b };
      fields.forEach((f, i) => {
        o[f] = vals[i];
      });
      return stripUndefined(o);
    }),
  );
